package com.aadil.ecommerce.responses;import com.aadil.ecommerce.entities.OrderEntity;import com.aadil.ecommerce.entities.OrderItemEntity;import org.springframework.stereotype.Component;import java.math.BigDecimal;import java.util.List;@Componentpublic class OrderResponseMapper {    private ProductOrderedResponse mapToOrderResponse(OrderItemEntity orderItem){        ProductOrderedResponse productOrderedResponse = new ProductOrderedResponse();        productOrderedResponse.setProductId(orderItem.getProduct().getProductId());        productOrderedResponse.setProductName(orderItem.getProduct().getProductName());        productOrderedResponse.setProductQuantity(orderItem.getQuantity());        productOrderedResponse.setUnitPrice(orderItem.getUnitPrice());        BigDecimal itemTotal = orderItem.getUnitPrice().multiply(BigDecimal.valueOf(orderItem.getQuantity()));        productOrderedResponse.setItemTotal(itemTotal);        return productOrderedResponse;    }    public OrderResponse mapToResponse (OrderEntity order){        OrderResponse orderResponse = new OrderResponse();        orderResponse.setOrderStatus(order.getOrderStatus());        orderResponse.setOrderId(order.getOrderId());        orderResponse.setCreatedAt(order.getCreatedAt());        orderResponse.setUpdatedAt(order.getUpdatedAt());        orderResponse.setTotalAmount(order.getTotalAmount());        List<ProductOrderedResponse> orderedItems = order.getOrderItems().stream().map(this::mapToOrderResponse).toList();        orderResponse.setOrderedItems(orderedItems);        return orderResponse;    }}